 GLAPI OSMesaContext GLAPIENTRY
 OSMesaCreateContextExt( GLenum format, GLint depthBits, GLint stencilBits,
                         GLint accumBits, OSMesaContext sharelist )
 {
    OSMesaContext osmesa;
    struct dd_function_table functions;
    GLint rind, gind, bind, aind;
    GLint redBits = 0, greenBits = 0, blueBits = 0, alphaBits =0;

    rind = gind = bind = aind = 0;
    if (format==OSMESA_RGBA) {
       redBits = CHAN_BITS;
       greenBits = CHAN_BITS;
       blueBits = CHAN_BITS;
       alphaBits = CHAN_BITS;
       rind = 0;
       gind = 1;
       bind = 2;
       aind = 3;
    }
    else if (format==OSMESA_BGRA) {
       redBits = CHAN_BITS;
       greenBits = CHAN_BITS;
       blueBits = CHAN_BITS;
       alphaBits = CHAN_BITS;
       bind = 0;
       gind = 1;
       rind = 2;
       aind = 3;
    }
    else if (format==OSMESA_ARGB) {
       redBits = CHAN_BITS;
       greenBits = CHAN_BITS;
       blueBits = CHAN_BITS;
       alphaBits = CHAN_BITS;
       aind = 0;
       rind = 1;
       gind = 2;
       bind = 3;
    }
    else if (format==OSMESA_RGB) {
       redBits = CHAN_BITS;
       greenBits = CHAN_BITS;
       blueBits = CHAN_BITS;
       alphaBits = 0;
       rind = 0;
       gind = 1;
       bind = 2;
    }
    else if (format==OSMESA_BGR) {
       redBits = CHAN_BITS;
       greenBits = CHAN_BITS;
       blueBits = CHAN_BITS;
       alphaBits = 0;
       rind = 2;
       gind = 1;
       bind = 0;
    }
 #if CHAN_TYPE == GL_UNSIGNED_BYTE
    else if (format==OSMESA_RGB_565) {
       redBits = 5;
       greenBits = 6;
       blueBits = 5;
       alphaBits = 0;
       rind = 0; /* not used */
       gind = 0;
       bind = 0;
    }
 #endif
    else {
       return NULL;
    }

    osmesa = (OSMesaContext) CALLOC_STRUCT(osmesa_context);
    if (osmesa) {
       osmesa->gl_visual = _mesa_create_visual( GL_FALSE,    /* double buffer */
                                                GL_FALSE,    /* stereo */
                                                redBits,
                                                greenBits,
                                                blueBits,
                                                alphaBits,
                                                depthBits,
                                                stencilBits,
                                                accumBits,
                                                accumBits,
                                                accumBits,
                                                alphaBits ? accumBits : 0,
                                                1            /* num samples */
                                                );
       if (!osmesa->gl_visual) {
          free(osmesa);
          return NULL;
       }

       /* Initialize device driver function table */
       _mesa_init_driver_functions(&functions);
       /* override with our functions */
       functions.GetString = get_string;
       functions.UpdateState = osmesa_update_state;
       functions.GetBufferSize = NULL;

       if (!_mesa_initialize_context(&osmesa->mesa,
                                     API_OPENGL_COMPAT,
                                     osmesa->gl_visual,
                                     sharelist ? &sharelist->mesa
                                               : (struct gl_context *) NULL,
                                     &functions)) {
          _mesa_destroy_visual( osmesa->gl_visual );
          free(osmesa);
          return NULL;
       }

       _mesa_enable_sw_extensions(&(osmesa->mesa));
       _mesa_enable_1_3_extensions(&(osmesa->mesa));
       _mesa_enable_1_4_extensions(&(osmesa->mesa));
       _mesa_enable_1_5_extensions(&(osmesa->mesa));
       _mesa_enable_2_0_extensions(&(osmesa->mesa));
       _mesa_enable_2_1_extensions(&(osmesa->mesa));

       osmesa->gl_buffer = _mesa_create_framebuffer(osmesa->gl_visual);
       if (!osmesa->gl_buffer) {
          _mesa_destroy_visual( osmesa->gl_visual );
          _mesa_free_context_data( &osmesa->mesa );
          free(osmesa);
          return NULL;
       }

       /* Create depth/stencil/accum buffers.  We'll create the color
        * buffer later in OSMesaMakeCurrent().
        */
       _swrast_add_soft_renderbuffers(osmesa->gl_buffer,
                                      GL_FALSE, /* color */
                                      osmesa->gl_visual->haveDepthBuffer,
                                      osmesa->gl_visual->haveStencilBuffer,
                                      osmesa->gl_visual->haveAccumBuffer,
                                      GL_FALSE, /* alpha */
                                      GL_FALSE /* aux */ );

       osmesa->format = format;
       osmesa->userRowLength = 0;
       osmesa->yup = GL_TRUE;
       osmesa->rInd = rind;
       osmesa->gInd = gind;
       osmesa->bInd = bind;
       osmesa->aInd = aind;

       _mesa_meta_init(&osmesa->mesa);

       /* Initialize the software rasterizer and helper modules. */
       {
 	 struct gl_context *ctx = &osmesa->mesa;
          SWcontext *swrast;
          TNLcontext *tnl;

 	 if (!_swrast_CreateContext( ctx ) ||
              !_vbo_CreateContext( ctx ) ||
              !_tnl_CreateContext( ctx ) ||
              !_swsetup_CreateContext( ctx )) {
             _mesa_destroy_visual(osmesa->gl_visual);
             _mesa_free_context_data(ctx);
             free(osmesa);
             return NULL;
          }

 	 _swsetup_Wakeup( ctx );

          /* use default TCL pipeline */
          tnl = TNL_CONTEXT(ctx);
          tnl->Driver.RunPipeline = _tnl_run_pipeline;

          ctx->Driver.MapRenderbuffer = osmesa_MapRenderbuffer;
          ctx->Driver.UnmapRenderbuffer = osmesa_UnmapRenderbuffer;

          /* Extend the software rasterizer with our optimized line and triangle
           * drawing functions.
           */
          swrast = SWRAST_CONTEXT( ctx );
          swrast->choose_line = osmesa_choose_line;
          swrast->choose_triangle = osmesa_choose_triangle;
-      }

-      _mesa_compute_version(ctx);
+         _mesa_compute_version(ctx);

-      /* Exec table initialization requires the version to be computed */
-      _mesa_initialize_exec_table(ctx);
-      _mesa_initialize_vbo_vtxfmt(ctx);
+         /* Exec table initialization requires the version to be computed */
+         _mesa_initialize_exec_table(ctx);
+         _mesa_initialize_vbo_vtxfmt(ctx);
+      }
    }
    return osmesa;
 }



